
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_wb97_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_wb97", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.166094583295566e+00, -4.082894880099127e+00, -3.966431274259477e+00, -3.805359413201196e+00, -3.586440605286932e+00, -3.296270596452879e+00, -2.925191445955004e+00, -2.473956444745250e+00, -1.962852533823851e+00, -1.443568636388566e+00, -9.384659675031380e-01, -5.382284011394987e-01, -4.423166357565517e-01, -3.282896735760674e-01, -1.893985111236733e-01, -5.939918342370124e-02, -1.179026886210881e-02, -1.158487675490093e-03, -7.198036503454446e-04, -1.481151528668350e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


